import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();

        // Camera rotated x degrees clockwise (positive), image appears rotated x degrees counter-clockwise
        // So the image's actual rotation from vertical (clockwise) is -x degrees
        long base = ((-x) % 360 + 360) % 360;

        int bestK = 0;
        long bestDev = Long.MAX_VALUE;

        for (int k = 0; k < 4; k++) {
            long total = (base + 90L * k) % 360;
            long dev = Math.min(total, 360 - total);
            if (dev < bestDev) {
                bestDev = dev;
                bestK = k;
            }
        }

        System.out.println(bestK);
    }
}
